type request struct{ op string; arg any; reply chan error }
type Store struct{ reqs chan request }

func NewStore(capacity int) *Store {
    return &Store{reqs: make(chan request, capacity)}
}

func (s *Store) Put(m Message) <-chan error {
    reply := make(chan error, 1)
    s.reqs <- request{op: "put", arg: m, reply: reply} // bounded admission
    return reply                                    // caller receives a future
}
